SET @q1_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q1_id, 'كيف حالك?', 'كيف حالك?', FALSE, 0),
(@q1_id, 'كيف حالك؟', 'كيف حالك؟', TRUE, 1),
(@q1_id, 'كيف حالك ?', 'كيف حالك ?', FALSE, 2),
(@q1_id, 'كيف حالك ؟', 'كيف حالك ؟', FALSE, 3);

-- Question 2
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz2_id, 'Where should you test your translations?', 'أين يجب أن تختبر ترجماتك؟', 'In the actual UI on multiple devices', 'Always preview translations in the real interface to catch formatting issues', 'عاين الترجمات دائماً في الواجهة الحقيقية لاكتشاف مشاكل التنسيق', 1);

SET @q2_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
