(@q2_id, 'In the actual UI on multiple devices', 'في الواجهة الفعلية على أجهزة متعددة', TRUE, 1),
(@q2_id, 'No testing needed', 'لا حاجة للاختبار', FALSE, 2),
(@q2_id, 'Only on desktop', 'على سطح المكتب فقط', FALSE, 3)

